    inline const wchar_t* Text(UINT id) noexcept
    {
        return ResourceText(id, false);
    }
    inline const wchar_t* EnglishText(UINT id) noexcept
    {
        return ResourceText(id, true);
    }

    inline UINT WindowFitResourceId(window_fit::Reason reason) noexcept
    {
        switch (reason)
        {
        case window_fit::Reason::Pending:
            return IDS_NATIVEWINDOWFITPENDING;
        case window_fit::Reason::Fitted:
            return IDS_NATIVEWINDOWFITFITTED;
        case window_fit::Reason::Busy:
            return IDS_NATIVEWINDOWFITBUSY;
        case window_fit::Reason::InvalidViewport:
            return IDS_NATIVEWINDOWFITINVALIDVIEWPORT;
        case window_fit::Reason::UnavailableDesktop:
            return IDS_NATIVEWINDOWFITUNAVAILABLEDESKTOP;
        case window_fit::Reason::NoWindow:
            return IDS_NATIVEWINDOWFITNOWINDOW;
        case window_fit::Reason::OwnWindow:
            return IDS_NATIVEWINDOWFITOWNWINDOW;
        case window_fit::Reason::NotResizable:
            return IDS_NATIVEWINDOWFITNOTRESIZABLE;
        case window_fit::Reason::Fullscreen:
            return IDS_NATIVEWINDOWFITFULLSCREEN;
        case window_fit::Reason::Maximized:
            return IDS_NATIVEWINDOWFITMAXIMIZED;
        case window_fit::Reason::Hung:
            return IDS_NATIVEWINDOWFITHUNG;
        case window_fit::Reason::UnavailableGeometry:
            return IDS_NATIVEWINDOWFITUNAVAILABLEGEOMETRY;
        case window_fit::Reason::ContextChanged:
            return IDS_NATIVEWINDOWFITCONTEXTCHANGED;
        case window_fit::Reason::NativeFailure:
            return IDS_NATIVEWINDOWFITNATIVEFAILURE;
        case window_fit::Reason::AppConstrained:
            return IDS_NATIVEWINDOWFITAPPCONSTRAINED;
        case window_fit::Reason::TimedOut:
            return IDS_NATIVEWINDOWFITTIMEDOUT;
        default:
            return IDS_NATIVEWINDOWFITUNAVAILABLE;
        }
    }
